import { bigint, integer, pgTable, text, uuid } from 'drizzle-orm/pg-core';

// The persistent shape of the domain (ADR 0008): one table per entity, ids and
// insertion order generated by the database. The models you see in
// `server/models/` are what the adapters return; this file only describes
// storage and never imports a use case.
//
// `seq` is a monotonic identity column, not the primary key: it exists so
// `list()` can return rows in insertion order, which Postgres does not
// guarantee on its own. `id` is a UUID generated by the database, so the port
// contract («create returns the entity with its id») holds for both adapters.

export const meetingTypes = pgTable('meeting_types', {
  seq: bigint('seq', { mode: 'number' }).generatedAlwaysAsIdentity(),
  id: uuid('id').primaryKey().defaultRandom(),
  name: text('name').notNull(),
  description: text('description').notNull(),
  durationMinutes: integer('duration_minutes').notNull(),
});

export const bookings = pgTable('bookings', {
  seq: bigint('seq', { mode: 'number' }).generatedAlwaysAsIdentity(),
  id: uuid('id').primaryKey().defaultRandom(),
  // Types are never edited or deleted, so the denormalized name cannot go
  // stale; the foreign key keeps every booking attached to a real type.
  meetingTypeId: uuid('meeting_type_id')
    .notNull()
    .references(() => meetingTypes.id),
  meetingTypeName: text('meeting_type_name').notNull(),
  guestName: text('guest_name').notNull(),
  // Epoch-ms, the unit of the domain. `bigint` matches it without a
  // precision loss and lets the exclusion constraint range over the interval.
  startMs: bigint('start_ms', { mode: 'number' }).notNull(),
  endMs: bigint('end_ms', { mode: 'number' }).notNull(),
});
